// Pure checks of the Phase-5 view models (assets/hq-carnet-intel.js) on the REAL JSON the server returns
// (tests/fixtures_carnet_intel.json, generated by tests/gen_fixtures_carnet_intel.py from the Python implementation).
// No browser, no server, no clock, no storage.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const I = require("../assets/hq-carnet-intel.js");
const FX = JSON.parse(readFileSync(new URL("./fixtures_carnet_intel.json", import.meta.url), "utf8"));
let groups = 0;
const group = (name, fn) => {
  try {
    fn();
    groups += 1;
  } catch (e) {
    console.error("FAIL group:", name);
    throw e;
  }
};
const clone = (x) => JSON.parse(JSON.stringify(x));
const P = (n) => "page-" + String(n).repeat(8);
const B = (n) => "block-" + String(n).repeat(8);
const pt = (over) => Object.assign({ page_id: P(1), block_id: B(1), page_title: "Note", at: 1790000000, value: "10.00", unit: "mm", mode: "sym", nominal: { v: "10", u: "mm" }, tol: { t: "0.02", u: "mm" }, verdict: "in", lo: "9.98", hi: "10.02" }, over);

group("labels are normalised exactly like the server (NFC, trim, collapse, case-fold)", () => {
  assert.equal(I.normLabel("  Ø   Arbre "), I.normLabel("ø arbre"));
  assert.equal(I.normLabel("e\u0301"), I.normLabel("é"));
  assert.notEqual(I.normLabel("a"), I.normLabel("b"));
  assert.equal(I.normLabel(null), "");
});

group("dates are timezone-free and deterministic", () => {
  assert.equal(I.fmtDate(1790000000), "2026-09-21 14:13");
  assert.equal(I.fmtDate(NaN), "");
  assert.equal(I.fmtDate("x"), "");
  assert.equal(I.dayStart("2026-09-21"), 1789948800);
  assert.equal(I.dayStart("21/09/2026"), null);
  assert.equal(I.dayStart("2026-13-40"), null);
});

group("navigation targets accept canonical ids only", () => {
  assert.deepEqual(I.target(P(1), B(1)), { pageId: P(1), blockId: B(1) });
  assert.deepEqual(I.target(P(1), null), { pageId: P(1), blockId: null });
  for (const [a, b] of [["page-x/../y", B(1)], [P(1), "block-../x"], [5, B(1)], [P(1), 5], ["", ""], [P(1) + "?x", B(1)]]) assert.equal(I.target(a, b), null);
});

group("decision filters: text, page, evidence, dates; order kept; input untouched", () => {
  const list = [
    { page_id: P(1), page_title: "Banc", at: 1790000000, text: "Retenir H7", evidence: [{ kind: "file", id: "a.pdf", state: "ok" }] },
    { page_id: P(2), page_title: "Arbre", at: 1790086400, text: "Changer le roulement", evidence: [] },
    { page_id: P(1), page_title: "Banc", at: 1790172800, text: "Valider ÉPAISSEUR", evidence: [] },
  ];
  const snap = JSON.stringify(list);
  assert.equal(I.filterDecisions(list, {}).length, 3);
  assert.deepEqual(I.filterDecisions(list, { query: "h7" }).map((d) => d.text), ["Retenir H7"]);
  assert.deepEqual(I.filterDecisions(list, { query: "épaisseur" }).length, 1);
  assert.deepEqual(I.filterDecisions(list, { query: "arbre" }).map((d) => d.page_id), [P(2)], "page title is searched too");
  assert.deepEqual(I.filterDecisions(list, { page: P(1) }).length, 2);
  assert.deepEqual(I.filterDecisions(list, { evidence: true }).length, 1);
  assert.deepEqual(I.filterDecisions(list, { from: "2026-09-22", to: "2026-09-22" }).map((d) => d.text), ["Changer le roulement"]);
  assert.deepEqual(I.filterDecisions(list, { page: P(1), query: "valider" }).length, 1);
  assert.deepEqual(I.filterDecisions(null, {}), []);
  assert.equal(JSON.stringify(list), snap);
});

group("series filters: verdict, unit, label, dates; empty series disappear; band recomputed", () => {
  const s = [
    { label: "Ø arbre", unit: "mm", points: [pt({ at: 1790000000 }), pt({ at: 1790086400, verdict: "out", value: "10.5" }), pt({ at: 1790172800, tol: { t: "0.05", u: "mm" }, lo: "9.95", hi: "10.05" })] },
    { label: "Longueur", unit: "in", points: [pt({ unit: "in", value: "3", verdict: "in" })] },
  ];
  assert.equal(I.filterSeries(s, {}).length, 2);
  const out = I.filterSeries(s, { verdict: "out" });
  assert.equal(out.length, 1);
  assert.equal(out[0].points.length, 1);
  assert.equal(out[0].out, 1);
  assert.equal(out[0].band.state, "exact", "after filtering, the remaining point's own band is exact");
  assert.equal(I.filterSeries(s, { unit: "in" }).length, 1);
  assert.equal(I.filterSeries(s, { query: "ØARBRE" }).length, 0, "no fuzzy: normalisation only");
  assert.equal(I.filterSeries(s, { query: " ø  arbre " }).length, 1);
  assert.equal(I.filterSeries(s, { from: "2026-09-22", to: "2026-09-22" })[0].points.length, 1);
  assert.equal(I.filterSeries(s, { verdict: "incompatible" }).length, 0);
  assert.deepEqual(I.unitsOf(s), ["in", "mm"]);
  assert.equal(I.filterSeries(s, {})[0].band.state, "variable");
});

group("band: exact only when EVERY point has the same exact bounds", () => {
  assert.deepEqual(I.bandOf([pt(), pt()]), { state: "exact", lo: "9.98", hi: "10.02", unit: "mm" });
  assert.equal(I.bandOf([pt(), pt({ lo: "9.9", hi: "10.1" })]).state, "variable");
  assert.equal(I.bandOf([pt(), pt({ lo: null, hi: null, verdict: "none" })]).state, "variable", "one point without tolerance: not exact");
  assert.equal(I.bandOf([pt({ lo: null, hi: null }), pt({ lo: null, hi: null })]).state, "none");
  assert.equal(I.bandOf([]).state, "none");
  assert.equal(I.bandText({ band: { state: "variable" } }), "Tolérance variable");
  assert.equal(I.bandText({ band: { state: "none" } }), "Sans tolérance");
  assert.equal(I.bandText({ band: { state: "exact", lo: "9.98", hi: "10.02", unit: "mm" } }), "Tolérance : 9.98 à 10.02 mm");
});

group("chart model: coordinates, bounds, band, single and flat series, unparseable values", () => {
  const s = { label: "a", unit: "mm", band: { state: "exact", lo: "9.98", hi: "10.02", unit: "mm" }, points: [pt({ at: 1, value: "10.00" }), pt({ at: 2, value: "10.05", verdict: "out" }), pt({ at: 3, value: "9.99" })] };
  const m = I.chartModel(s, { w: 320, h: 160 });
  assert.equal(m.plotted, 3);
  assert.equal(m.points.length, 3);
  for (const p of m.points) {
    assert.ok(p.x >= m.margin.l && p.x <= m.w - m.margin.r, "x inside the plot");
    assert.ok(p.y >= m.margin.t && p.y <= m.h - m.margin.b, "y inside the plot");
  }
  assert.ok(m.points[1].y < m.points[0].y, "higher value is higher on screen");
  assert.ok(m.points[0].x < m.points[1].x && m.points[1].x < m.points[2].x, "time flows left to right");
  assert.ok(m.band && m.band.y1 < m.band.y2, "band drawn, upper bound above lower");
  assert.equal(m.points[1].mark, "◆");
  assert.equal(m.points[0].mark, "●");
  assert.match(m.path, /^M[\d.]+ [\d.]+ L/);
  assert.equal(I.chartModel(Object.assign({}, s, { band: { state: "variable" } })).band, null, "no band unless exact");
  const one = I.chartModel({ label: "a", unit: "mm", band: { state: "none" }, points: [pt()] });
  assert.equal(one.points.length, 1);
  assert.ok(Number.isFinite(one.points[0].x) && Number.isFinite(one.points[0].y));
  const flat = I.chartModel({ label: "a", unit: "mm", band: { state: "none" }, points: [pt({ at: 1 }), pt({ at: 2 })] });
  assert.ok(flat.points.every((p) => Number.isFinite(p.y)), "equal values never divide by zero");
  const same = I.chartModel({ label: "a", unit: "mm", band: { state: "none" }, points: [pt({ at: 5 }), pt({ at: 5, value: "11" })] });
  assert.ok(same.points.every((p) => Number.isFinite(p.x)), "same timestamp never divides by zero");
  const mixed = I.chartModel({ label: "a", unit: "mm", band: { state: "none" }, points: [pt({ value: "abc" }), pt({ value: "1e5x" }), pt({ at: 9 })] });
  assert.equal(mixed.plotted, 1);
  assert.equal(mixed.total, 3, "the table still lists every point");
  assert.equal(I.chartModel({ label: "a", unit: "mm", points: [pt({ value: "x" })] }), null);
  assert.equal(I.chartModel(null), null);
});

group("the accessible table carries every fact of the chart", () => {
  const s = { label: "Ø", unit: "mm", band: { state: "variable" }, points: [pt({ verdict: "out" }), pt({ mode: "none", tol: null, nominal: null, verdict: "none", lo: null, hi: null }), pt({ mode: "bounds", tol: { lo: "9.98", hi: "10.02", u: "mm" } }), pt({ mode: "pct", tol: { p: "1" } }), pt({ verdict: "incompatible", lo: null, hi: null })] };
  const rows = I.tableRows(s);
  assert.equal(rows.length, 5);
  assert.deepEqual(rows.map((r) => r.verdict), ["Hors tolérance", "Sans tolérance", "Dans la tolérance", "Dans la tolérance", "Unités incompatibles"]);
  assert.equal(rows[0].tolerance, "± 0.02 mm");
  assert.equal(rows[1].tolerance, "sans tolérance");
  assert.equal(rows[1].nominal, "—");
  assert.equal(rows[2].tolerance, "9.98 à 10.02 mm");
  assert.equal(rows[3].tolerance, "± 1 %");
  assert.ok(rows.every((r) => r.mark && r.value.endsWith(" mm")), "every verdict has a shape, never colour alone");
  const marks = new Set(Object.values(I.VERDICT_MARK));
  assert.equal(marks.size, 4, "four verdicts, four distinct shapes");
  assert.match(I.seriesSummary(s), /5 mesures, 1 hors tolérance/);
});

group("REAL cockpit response: model, tiles, honest notes, references", () => {
  const m = I.cockpitModel(FX.cockpit);
  assert.equal(m.title, "Banc d'essai");
  assert.deepEqual(m.tiles.map((t) => t.key), ["pages", "decisions", "measurements", "images", "drawings", "sources", "files"]);
  assert.equal(m.tiles.find((t) => t.key === "measurements").note, "2 hors tolérance");
  assert.ok(m.notes.some((n) => /Tâches non disponibles/.test(n)), "tasks are declared unavailable, never faked");
  assert.equal(m.empty, false);
  const byLabel = Object.fromEntries(I.refRows(FX.cockpit).map((r) => [r.label, r]));
  assert.equal(byLabel["plan-2"].stateLabel, "Introuvable", "the page now points at a drawing that does not exist");
  assert.equal(byLabel["plan-9"].stateLabel, "Introuvable");
  assert.ok(byLabel["plan-2"].first && byLabel["plan-2"].first.blockId, "every reference links back to a source block");
  const frozen = Object.fromEntries(I.refRows(FX.snapshot_cockpit).map((r) => [r.label, r]));
  assert.equal(frozen["plan-1"].stateLabel, "Disponible", "the frozen state still points at plan-1, which exists");
  assert.equal(frozen["Inbox/a.pdf"].kindLabel, "Fichier");
  assert.equal(I.cockpitModel(null), null);
  const trunc = I.cockpitModel(Object.assign(clone(FX.cockpit), { truncated: { pages: false, decisions: true, series: true, points: true } }));
  assert.equal(trunc.notes.filter((n) => /limité/.test(n)).length, 3);
});

group("REAL cockpit response: series keep their own metadata, tolerance variable, units never merged", () => {
  const mm = FX.cockpit.series.find((s) => s.unit === "mm");
  const inch = FX.cockpit.series.find((s) => s.unit === "in");
  assert.equal(mm.points.length, 3);
  assert.equal(inch.points.length, 1);
  assert.equal(I.bandText(mm), "Tolérance variable", "0.02 then 0.05: no single band");
  assert.equal(I.bandText(inch), "Tolérance : 0.393 à 0.395 in");
  assert.equal(I.chartModel(mm).band, null);
  assert.ok(I.chartModel(inch).band);
  const out = I.filterSeries(FX.cockpit.series, { verdict: "out" });
  assert.equal(out.length, 1);
  assert.deepEqual(out[0].points.map((p) => p.value), ["10.2", "10.04"], "the edit after the snapshot made the first point out of tolerance");
  assert.equal(out[0].out, 2);
  assert.equal(I.tableRows(mm).map((r) => r.tolerance).join("|"), "± 0.02 mm|± 0.02 mm|± 0.05 mm");
});

group("REAL decision trail: canonical fields only", () => {
  assert.equal(FX.cockpit.decisions.length, 0, "the live page no longer has the decision");
  assert.equal(FX.snapshot_cockpit.decisions.length, 1, "the freeze still does");
  const d = FX.snapshot_cockpit.decisions[0];
  assert.deepEqual(Object.keys(d).sort(), ["anchor", "at", "block_id", "evidence", "page_id", "page_title", "text"]);
  assert.equal(d.text, "Retenir l'alésage H7");
  assert.equal(d.evidence[0].kind, "file");
  assert.equal(d.evidence[0].state, "ok");
  assert.equal(I.filterDecisions(FX.snapshot_cockpit.decisions, { evidence: true }).length, 1);
});

group("REAL checkpoint diff: labels for every change, overlay states, ghosts, identity note", () => {
  const dm = I.diffModel(FX.diff_checkpoint);
  assert.equal(dm.scope, "page");
  assert.match(dm.base, /^Checkpoint « avant essai » — \d{4}-\d\d-\d\d \d\d:\d\d$/);
  assert.equal(dm.to, "Version actuelle");
  assert.match(dm.note, /identifiant/);
  const d = FX.diff_checkpoint.diff;
  assert.equal(I.pageDiffSummary(d), "1 ajouté, 3 modifiés, 1 supprimé");
  const labels = d.changed.map((c) => I.changeLabel(c));
  assert.ok(labels.some((l) => /Texte modifié/.test(l)));
  assert.ok(labels.some((l) => /Mesure modifiée · ?\(valeur\)|Mesure modifiée \(valeur\)/.test(l)), labels.join(" / "));
  assert.ok(labels.some((l) => /Version du croquis changée.*plan-1 → plan-2/.test(l)), labels.join(" / "));
  const ov = I.overlayOf(d);
  assert.equal(ov.available, true);
  assert.equal(Object.values(ov.states).filter((s) => s.state === "added").length, 1);
  assert.equal(Object.values(ov.states).filter((s) => s.state === "changed").length, 3);
  assert.ok(Object.values(ov.states).every((s) => /^(Ajouté|Modifié)/.test(s.label)), "every state is a WORD, not only a colour");
  assert.equal(ov.ghosts.length, 1);
  assert.equal(ov.ghosts[0].label, "Supprimé");
  assert.equal(ov.ghosts[0].type, "decision");
});

group("REAL snapshot diff: project level rows with exact statuses", () => {
  const dm = I.diffModel(FX.diff_snapshot);
  assert.equal(dm.scope, "project");
  assert.match(dm.base, /^Jalon « Gel conception » — /);
  assert.deepEqual(dm.pages.map((p) => p.status), ["changed", "unchanged"]);
  assert.equal(dm.pages[0].statusLabel, "Modifiée");
  assert.equal(dm.pages[1].summary, "");
  assert.equal(dm.counts.changed, 1);
  assert.equal(I.diffModel({ scope: "bogus" }), null);
  const removed = I.diffModel({ scope: "project", base: FX.diff_snapshot.base, to: { kind: "current" }, counts: {}, pages: [{ page_id: P(1), title: "x", status: "removed", reason: "trashed", counts: null }] });
  assert.equal(removed.pages[0].reason, "à la corbeille");
});

group("overlay of a text-only page is unavailable (no stable block ids)", () => {
  const ov = I.overlayOf({ mode: "text_only", added: [], removed: [], changed: [], counts: { added: 0, removed: 0, changed: 1 } });
  assert.equal(ov.available, false);
  assert.deepEqual(ov.states, {});
  assert.equal(I.overlayOf(null).available, false);
});

group("baselines: explicit ids only; a date resolves visibly and never silently", () => {
  const c = I.baselineChoices(FX.baselines);
  assert.equal(c.checkpoints.length, 1);
  assert.equal(c.snapshots.length, 1);
  assert.equal(c.latestCheckpoint, FX.baselines.checkpoints[0].id);
  assert.match(c.checkpoints[0].text, /^avant essai — /);
  const bad = I.baselineChoices({ checkpoints: [{ id: "7 days ago", at: 1, label: "x" }], snapshots: [{ id: "snap-zzz", at: 1, label: "x" }] });
  assert.deepEqual([bad.checkpoints.length, bad.snapshots.length], [0, 0], "a non-id never becomes a baseline");
  assert.match(I.resolvedText(FX.baselines, "checkpoint"), /^Baseline disponible la plus proche avant cette date : checkpoint « avant essai » — /);
  assert.match(I.resolvedText({ resolved: { checkpoint: null, snapshot: null } }, "snapshot"), /^Aucun jalon à cette date ou avant : rien à comparer\.$/);
  assert.match(I.resolvedText({}, "checkpoint"), /rien à comparer/);
});

group("snapshots: rows, integrity wording, verify model never overclaims", () => {
  const rows = I.snapshotRows(FX.snapshots);
  assert.equal(rows[0].label, "Gel conception");
  assert.equal(rows[0].integrityLabel, "Intègre");
  assert.equal(I.snapshotRows({ snapshots: [{ id: "snap-" + "0".repeat(24), label: "x", created_at: 1, pages: 1, integrity: "corrupt" }] })[0].ok, false);
  const v = I.verifyModel(FX.verify);
  assert.equal(v.drift, 1);
  assert.match(v.summary, /1 référence\(s\) ont changé/);
  const drawing = v.rows.find((r) => r.bucket === "drawings");
  assert.equal(drawing.label, "Modifié depuis le jalon");
  assert.equal(drawing.changed, true);
  assert.ok(v.rows.some((r) => r.label === "Déjà introuvable au jalon"));
  const clean = I.verifyModel({ counts: { unchanged: 2, modified: 0, missing: 0, still_missing: 0, appeared: 0 }, refs: {}, integrity: "ok" });
  assert.equal(clean.drift, 0);
  assert.match(clean.summary, /inchangées/);
  assert.match(I.SNAPSHOT_CLAIM, /ne sont pas copiés/);
  assert.doesNotMatch(I.SNAPSHOT_CLAIM, /archiv|sauvegard/i, "never claims an archival bundle");
});

group("snapshot input validation mirrors the server limits", () => {
  assert.equal(I.validSnapshotInput("", "").ok, false);
  assert.equal(I.validSnapshotInput("   ", "").ok, false);
  assert.deepEqual(I.validSnapshotInput("  Gel  ", " note "), { ok: true, label: "Gel", note: "note" });
  assert.equal(I.validSnapshotInput("x".repeat(81), "").ok, false);
  assert.equal(I.validSnapshotInput("x".repeat(80), "").ok, true);
  assert.equal(I.validSnapshotInput("x", "n".repeat(401)).ok, false);
  assert.equal(I.validSnapshotInput("a\u0000b", "").ok, false);
});

group("report item wire shape: live is pinned by fingerprint, snapshot by id", () => {
  const live = I.reportItem(FX.cockpit);
  assert.equal(live.kind, "project_overview");
  assert.match(live.project_id, /^proj-/);
  assert.match(live.fingerprint, /^[0-9a-f]{32}$/);
  assert.equal(live.snapshot_id, undefined);
  const frozen = I.reportItem(FX.snapshot_cockpit);
  assert.deepEqual(Object.keys(frozen).sort(), ["kind", "label", "snapshot_id"]);
  assert.match(frozen.snapshot_id, /^snap-[0-9a-f]{24}$/);
  assert.equal(I.reportItem({ project: { id: null, name: null }, fingerprint: "0".repeat(32) }).project_id, "none");
  assert.equal(I.reportItem({ project: { id: "proj-x/../y" }, fingerprint: "0".repeat(32) }), null);
  assert.equal(I.reportItem({ project: { id: "proj-abc" }, fingerprint: "zz" }), null);
  assert.equal(I.reportItem(null), null);
  for (const bad of ["corrupt", "invalid", undefined]) {
    const c = JSON.parse(JSON.stringify(FX.snapshot_cockpit));
    c.snapshot.integrity = bad;
    assert.equal(I.reportItem(c), null, "a broken seal is never offered as trusted frozen state: " + bad);
  }
});

group("the module has no DOM, network, storage, clock or dynamic code", () => {
  const src = readFileSync(new URL("../assets/hq-carnet-intel.js", import.meta.url), "utf8").replace(/\/\*[\s\S]*?\*\//g, "").split("\n").filter((l) => !/^\s*\/\//.test(l)).join("\n");
  for (const banned of ["document.", "window.", "fetch(", "XMLHttpRequest", "localStorage", "sessionStorage", "indexedDB", "Date.now", "new Date()", "eval(", "new Function", "innerHTML", "setTimeout", "navigator."]) assert.ok(!src.includes(banned), banned);
});

console.log("check_hq_carnet_intel: " + groups + " groups OK");
